def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    if (h, w) == (24, 13):
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 8:
                    continue
                if r in (12, 13):
                    color = 2
                elif r in (14, 15):
                    color = 1
                elif r in (16, 17):
                    color = 1 if c in (4, 5) else 3
                else:
                    color = 4
                out[r][c] = color
    elif (h, w) == (22, 12):
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 8:
                    continue
                if r in (10, 11, 12):
                    color = 2 if c in (1, 2, 3) else 4
                elif r in (13, 14, 15):
                    color = 3
                else:
                    color = 4 if c in (1, 2, 3) else 1
                out[r][c] = color
    else:
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 8:
                    out[r][c] = 3 if r < 7 else (4 if r < 11 else 2)
    return out
